using NetTopologySuite.Features;
using Meteo.Core.Export;
using Meteo.Core.Styling;
using Meteo.Core.Vector;

namespace Meteo.Core.Geo;

/// <summary>Static geo layers embedded in the assembly (generated by tools/Meteo.GeoPrep).</summary>
public static class GeoResources
{
    private static readonly Lazy<FeatureCollection> ReliefFc = new(() => Load("relief.geojson"));
    private static readonly Lazy<FeatureCollection> BordersFc = new(() => Load("borders.geojson"));

    private static FeatureCollection Load(string name)
    {
        var asm = typeof(GeoResources).Assembly;
        var resName = asm.GetManifestResourceNames().FirstOrDefault(n => n.EndsWith(name, StringComparison.OrdinalIgnoreCase))
            ?? throw new InvalidOperationException($"Embedded resource {name} not found. Run tools/Meteo.GeoPrep.");
        using var s = asm.GetManifestResourceStream(resName)!;
        return GeoJson.ReadFeatures(s);
    }

    /// <summary>Hypsometric relief: background rectangle + cumulative elevation bands.</summary>
    public static VectorLayer Relief(GridDefinition grid)
    {
        var layer = new VectorLayer { Title = "Reliéf" };
        var bg = new NetTopologySuite.Geometries.GeometryFactory().ToGeometry(new NetTopologySuite.Geometries.Envelope(grid.X0, grid.X1, grid.Y0, grid.Y1));
        layer.Polygons.Add(new StyledPolygon(bg, ColorScale.ReliefBase));
        var scale = ColorScale.Relief;
        foreach (var f in ReliefFc.Value)
        {
            double min = Convert.ToDouble(f.Attributes["min"]);
            int idx = Array.IndexOf(scale.Levels, min);
            string color = idx >= 0 ? scale.Colors[idx] : "#CCCCCC";
            layer.Polygons.Add(new StyledPolygon(f.Geometry, color, Value: min));
        }
        layer.Legend.Add(new LegendItem(ColorScale.ReliefBase, "< 200 m"));
        for (int k = 0; k < scale.Levels.Length; k++) layer.Legend.Add(new LegendItem(scale.Colors[k], scale.Labels[k]));
        return layer;
    }

    /// <summary>Czech border (thick) and neighbouring countries (thin), as outlines.</summary>
    public static VectorLayer Borders()
    {
        var layer = new VectorLayer { Title = "Hranice" };
        foreach (var f in BordersFc.Value.OrderBy(f => f.Attributes["main"] is true))
        {
            bool main = f.Attributes["main"] is true;
            layer.Lines.Add(new StyledLine(f.Geometry.Boundary, main ? ColorScale.BorderMain : ColorScale.BorderOther, main ? 2.2 : 1.0, Dashed: !main));
        }
        return layer;
    }

    /// <summary>Czech Republic polygon (UTM 33N).</summary>
    public static NetTopologySuite.Geometries.Geometry CzechRepublic =>
        BordersFc.Value.First(f => f.Attributes["main"] is true).Geometry;
}
